  "35mm film": { name: "35mm Film", url: "https://wiki.warframe.com/w/35mm_Film", revid: 2720913, fetched: "2026-10-03T20:35:15.619135Z", foundText: "35mm Film is a Hex Treasure found within H\xF6llvania.", drops: [], otherSections: [{ heading: "Acquisition", text: "35mm Film can be found scattered across any H\xF6llvania missions as an interactable pickup." }, { heading: "Enemy Drop Tables", text: "Drop Table Chance [ 4 ] Item Chance [ 1 ] Chance [ 5 ] Expected Kills [ 6 ] Quantity [ 2 ] Avg. Per roll attempt [ 7 ] No enemy drop tables with this item Sourced from the official drop table repository. See Module:DropTables/data to edit on the wiki." }, { heading: "Acquisition", text: "*35mm Film can be found scattered across any H\xF6llvania missions as an interactable pickup." }] },
  "ack & brunt incarnon genesis": { name: "Ack & Brunt Incarnon Genesis", url: "https://wiki.warframe.com/w/Ack_&_Brunt_Incarnon_Genesis", revid: 2787344, fetched: "2026-10-03T20:35:15.619135Z", foundText: "Purchased from Cavalero for 120 Platinum, complete with the resources used in its installation.", drops: [], otherSections: [{ heading: "Acquisition", text: "Upon completion of The Duviri Paradox and Angels of the Zariman, and unlocking The Steel Path, players can earn Ack & Brunt Incarnon Genesis from The Circuit's Steel Path to place on their Ack & Brunt with the help of Cavalero in the Chrysalith. This Incarnon Genesis form grants it evolutions to a transformation and newfound strength. Purchased from Cavalero for 120 Platinum, complete with the resources used in its installation. This purchase can only be made once." }, { heading: "Acquisition", text: "*Upon completion of The Duviri Paradox and Angels of the Zariman, and unlocking The Steel Path, players can earn Ack & Brunt Incarnon Genesis from The Circuit's Steel Path to place on their Ack & Brunt with the help of Cavalero in the Chrysalith. This Incarnon Genesis form grants it evolutions to a transformation and newfound strength." }] },
  "adra mutagen": { name: "Adra Mutagen", url: "https://wiki.warframe.com/w/Adra_Mutagen", revid: 2620252, fetched: "2026-10-03T20:35:15.619135Z", foundText: "The Adra Mutagen blueprint can be acquired after reaching the Rank of Stranger with the Entrati and buying it from Son for 1,250 Standing.", drops: [], otherSections: [{ heading: "Acquisition", text: "The Adra Mutagen blueprint can be acquired after reaching the Rank of Stranger with the Entrati and buying it from Son for 1,250 Standing." }] },
  "adramal alloy": { name: "Adramal Alloy", url: "https://wiki.warframe.com/w/Adramal_Alloy", revid: 2711806, fetched: "2026-10-03T20:35:15.619135Z", foundText: "The reusable blueprint can be purchased from Otak for 1,000 Standing, requiring Rank 0 - Neutral with the Entrati.", drops: [], otherSections: [{ heading: "Acquisition", text: "The reusable blueprint can be purchased from Otak for 1,000 Standing, requiring Rank 0 - Neutral with the Entrati." }] },
  adramalium: { name: "Adramalium", url: "https://wiki.warframe.com/w/Adramalium", revid: 2711807, fetched: "2026-10-03T20:35:15.619135Z", foundText: "Adramalium is an ore that can be found in the Cambion Drift.", drops: [], otherSections: [{ heading: "Acquisition", text: "Mining yellow mineral veins in the Cambion Drift Rolizor and Spitia Infested Cysts in the Cambion Drift" }] },
  "affinity booster": { name: "Affinity Booster", url: "https://wiki.warframe.com/w/Affinity_Booster", revid: 2815615, fetched: "2026-10-03T20:35:15.619135Z", foundText: "Affinity Boosters doubles the amount of affinity earned from pickups and mission rewards.", drops: [], otherSections: [{ heading: "Acquisition", text: "Can be bought from the Market with Platinum. A 3-day booster costs 40 Platinum, a 7-day booster costs 80 Platinum, and a 30-day booster costs 200 Platinum. Can be obtained randomly from Daily Tribute. The booster's duration depends on the total amount of login days: (3 \xD7 [1 + Day \xF7 100]), to a cap of 93 hours from 3,000 days onward. 3-day boosters may also be obtained for free by the following methods: As a reward from daily Sorties or weekly Archon Hunts. As a reward from The Descendia. As a reward from The Circuit. Rare or Reinforced Storage Containers may reward a 30-minute or 1-hour variant respectively. A 90-day booster can be obtained by purchasing the Prime Access Complete or Accessories Pack. A 1-day booster can be obtained as a reward from the Void Surplus offering for sale by Baro Ki'Teer." }, { heading: "Acquisition", text: "*Can be bought from the Market with Platinum." }] },
  aggristone: { name: "Aggristone", url: "https://wiki.warframe.com/w/Aggristone", revid: 2724078, fetched: "2026-10-03T20:35:15.619135Z", foundText: "Aggristone is a common resource found within Duviri.", drops: [], otherSections: [{ heading: "Acquisition", text: "Aggristone can be obtained by completing Spiral objectives, The Circuit or by destroying Aggristone Formations found throughout Duviri's landscape." }] },
  agnovidisc: { name: "Agnovidisc", url: "https://wiki.warframe.com/w/Agnovidisc", revid: 2737442, fetched: "2026-10-03T20:35:15.619135Z", foundText: "Agnovidisc is a common resource that can be found in The Perita Rebellion within the Dark Refractory. It can be acquired from enemies, lockers and loot containers.", drops: [{ missionType: "The Perita Rebellion", source: "Recall: Prime Vanguard", rotationOrTable: "A", chance: 0.03, quantity: 150, nodes: ["Recall: Prime Vanguard, Dark Refractory"] }, { missionType: "The Perita Rebellion", source: "Recall: Dactolyst", rotationOrTable: "A", chance: 0.03, quantity: 150, nodes: ["Recall: Dactolyst, Dark Refractory"] }, { missionType: "The Perita Rebellion", source: "Recall: Hunhullus", rotationOrTable: "A", chance: 0.03, quantity: 150, nodes: ["Recall: Hunhullus, Dark Refractory"] }], otherSections: [{ heading: "Enemy Drop Tables", text: "Drop Table Chance [ 4 ] Item Chance [ 1 ] Chance [ 5 ] Expected Kills [ 6 ] Quantity [ 2 ] Avg. Per roll attempt [ 7 ] No enemy drop tables with this item Sourced from the official drop table repository. See Module:DropTables/data to edit on the wiki." }] },
