  amarast: { name: "Amarast", url: "https://wiki.warframe.com/w/Amarast", revid: 2749152, fetched: "2026-10-03T20:35:15.619135Z", foundText: "Mined from Orb Vallis. Dropped from storage containers found in Orb Vallis, yielding varying units.", drops: [], otherSections: [{ heading: "Acquisition", text: "Mined from Orb Vallis. Dropped from storage containers found in Orb Vallis, yielding varying units." }] },
  "amber archon shard": { name: "Amber Archon Shard", url: "https://wiki.warframe.com/w/Amber_Archon_Shard", revid: 2764183, fetched: "2026-10-03T20:35:15.619135Z", drops: [], otherSections: [{ heading: "Acquisition", text: "Archon Shards are awarded from Archon Hunts: Crimson from Archon Amar, Amber from Archon Nira, and Azure from Archon Boreal. The Shard has an 80% chance of being a normal variant and 20% of being Tauforged. If a normal variant is awarded, the chance of receiving a Tauforged increases by 20% which resets upon earning one, tracked individually for each shard type. Taking the increasing drop rates after not getting a Tauforged into consideration, the effective chance for a Tauforged is around 39.83%. Crimson, Amber, and Azure Archon Shards are available as common loot from the Netracells or Deep Archimedea, with their Tauforged variants able to be rolled as rare loot. Topaz, Violet, and Emerald Archon Shards are primarily obtainable through Coalescent Fusion of two Crimson, Amber, and Azure Shards. All normal shards, not including the coalescent shards, are possible prizes from the Steel Path version of The Descendia after completing Infernum 21. All shards, including Coalescent and Tauforged Shards, can be obtained as rewards from Temporal Archimedea. Nearly Guaranteed Archon Hunt 80%* 1 \u2013 2 4 \xB1 1 20%* 5 31 \xB1 10 52.5% 1 \u2013 2 9 \xB1 3 12.5% 8 52 \xB1 17 Deep Archimedea Uncommon Reward Pool 52.5% 1 \u2013 2 9 \xB1 3 12.5% 8 52 \xB1 17 Rare Reward Pool 39.4% 2 \u2013 3 14 \xB1 5 25.6% 3 \u2013 4 23 \xB1 8 Legendary Reward Pool 50% 2 10 \xB1 3 Temporal Archimedea Uncommon Reward Pool 46% 2 \u2013 3 11 \xB1 4 10.95% 9 \u2013 10 60 \xB1 20 Rare Reward Pool 22.35% 4 \u2013 5 27 \xB1 9 16.77% 5 \u2013 6 38 \xB1 13 14.52% 6 \u2013 7 44 \xB1 15 Fused Tauforged 10.92% 9 \u2013 10 60 \xB1 20 Legendary Reward Pool 27.33% 3 \u2013 4 22 \xB1 7 Fused Tauforged 20.5% 4 \u2013 5 30 \xB1 10 *Tauforged variants' drop chance increases if a normal variant is awarded." }] },
  "amp arcane adapter": { name: "Amp Arcane Adapter", url: "https://wiki.warframe.com/w/Amp_Arcane_Adapter", revid: 2725e3, fetched: "2026-10-03T20:35:15.619135Z", foundText: "Can be purchased from Cavalero for 20,000 Standing, requiring Rank 5 - Angel with The Holdfasts.", drops: [], otherSections: [{ heading: "Acquisition", text: "Can be given as a reward in The Descendia on Floor 21 in Normal mode, and Floors 4 and 11 in Steel Path." }, { heading: "Acquisition", text: "*Can be purchased from Cavalero for 20,000 Standing, requiring Rank 5 - Angel with The Holdfasts." }] },
  "angstrum incarnon genesis": { name: "Angstrum Incarnon Genesis", url: "https://wiki.warframe.com/w/Angstrum_Incarnon_Genesis", revid: 2814454, fetched: "2026-10-03T20:35:15.619135Z", foundText: "Purchased from Cavalero for 120 Platinum, complete with the resources used in its installation.", drops: [], otherSections: [{ heading: "Acquisition", text: "Upon completion of The Duviri Paradox and Angels of the Zariman, and unlocking The Steel Path, players can earn Angstrum Incarnon Genesis from The Circuit's Steel Path to place on their Angstrum with the help of Cavalero in the Chrysalith. This Incarnon Genesis form grants it evolutions to a transformation and newfound strength. Purchased from Cavalero for 120 Platinum, complete with the resources used in its installation. This purchase can only be made once." }, { heading: "Acquisition", text: "*Upon completion of The Duviri Paradox and Angels of the Zariman, and unlocking The Steel Path, players can earn Angstrum Incarnon Genesis from The Circuit's Steel Path to place on their Angstrum with the help of Cavalero in the Chrysalith. This Incarnon Genesis form grants it evolutions to a transformation and newfound strength." }] },
  "anku incarnon genesis": { name: "Anku Incarnon Genesis", url: "https://wiki.warframe.com/w/Anku_Incarnon_Genesis", revid: 2810581, fetched: "2026-10-03T20:35:15.619135Z", foundText: "Purchased from Cavalero for 120 Platinum, complete with the resources used in its installation.", drops: [], otherSections: [{ heading: "Acquisition", text: "Upon completion of The Duviri Paradox and Angels of the Zariman, and unlocking The Steel Path, players can earn Anku Incarnon Genesis from The Circuit's Steel Path to place on their Anku with the help of Cavalero in the Chrysalith. This Incarnon Genesis form grants it evolutions to a transformation and newfound strength. Purchased from Cavalero for 120 Platinum, complete with the resources used in its installation. This purchase can only be made once." }, { heading: "Acquisition", text: "*Upon completion of The Duviri Paradox and Angels of the Zariman, and unlocking The Steel Path, players can earn Anku Incarnon Genesis from The Circuit's Steel Path to place on their Anku with the help of Cavalero in the Chrysalith. This Incarnon Genesis form grants it evolutions to a transformation and newfound strength." }] },
  "anomaly shard": { name: "Anomaly Shard", url: "https://wiki.warframe.com/w/Anomaly_Shard", revid: 2805903, fetched: "2026-10-03T20:35:15.619135Z", foundText: "Anomaly Shard is a special resource that can be obtained from completing a Murex ship in the Veil Proxima.", drops: [], otherSections: [{ heading: "Acquisition", text: "1 Anomaly Shard is awarded for clearing a Murex ship by killing 20 Sentients aboard. The Murex appearance is marked as a red flashing node on Grineer -controlled Veil Proxima missions." }, { heading: "Acquisition", text: "*1 Anomaly Shard is awarded for clearing a Murex ship by killing 20 Sentients aboard. The Murex appearance is marked as a red flashing node on Grineer-controlled Veil Proxima missions." }] },
