  "atmo systems": { name: "Atmo Systems", url: "https://wiki.warframe.com/w/Atmo_Systems", revid: 2729194, fetched: "2026-10-03T20:35:15.619135Z", foundText: "The Atmo Systems is a crafting component that can be acquired as rewards from Heist Bounties offered by Vox Solaris or purchased from Little Duck.", drops: [{ missionType: "Profit-Taker Bounty", source: "Profit-Taker Orb Bounty Phase 1", rotationOrTable: "A", chance: 0.1, quantity: 5, nodes: ["Fortuna, Venus; must be Rank 5: Old Mate with Solaris United syndicate to access"] }, { missionType: "Profit-Taker Bounty", source: "Profit-Taker Orb Bounty Phase 3", rotationOrTable: "A", chance: 0.1, quantity: 5, nodes: ["Fortuna, Venus; must be Rank 5: Old Mate with Solaris United syndicate to access"] }, { missionType: "Profit-Taker Bounty", source: "Profit-Taker Orb Bounty Phase 4", rotationOrTable: "A", chance: 0.1143, quantity: 5, nodes: ["Fortuna, Venus; must be Rank 5: Old Mate with Solaris United syndicate to access"] }, { missionType: "Profit-Taker Bounty", source: "Profit-Taker Orb Bounty Phase 2", rotationOrTable: "A", chance: 0.1, quantity: 5, nodes: ["Fortuna, Venus; must be Rank 5: Old Mate with Solaris United syndicate to access"] }], otherSections: [{ heading: "Enemy Drop Tables", text: "Drop Table Chance [ 4 ] Item Chance [ 1 ] Chance [ 5 ] Expected Kills [ 6 ] Quantity [ 2 ] Avg. Per roll attempt [ 7 ] No enemy drop tables with this item Sourced from the official drop table repository. See Module:DropTables/data to edit on the wiki." }, { heading: "Acquisition", text: "Can be purchased from Little Duck for 2,500 Standing at Rank 2 - Agent." }] },
