  "brickie muon battery": { name: "Brickie Muon Battery", url: "https://wiki.warframe.com/w/Brickie_Muon_Battery", revid: 2720999, fetched: "2026-10-03T20:35:15.619135Z", foundText: "Brickie Muon Battery is a Resource extracted from Brickie, a Servofish found in ponds during warm weather in Orb Vallis.", drops: [], otherSections: [{ heading: "Acquisition", text: 'Muon Batteries are acquired by dismantling Brickies caught through Fishing. Go to The Business in Fortuna, select the desired amount of Brickies available, and select the " Dismantle " option to extract the components. Each Brickie yields one Muon Battery. Muon Batteries may also be acquired by breaking containers around the map.' }, { heading: "Acquisition", text: 'Muon Batteries are acquired by dismantling Brickies caught through Fishing. Go to The Business in Fortuna, select the desired amount of Brickies available, and select the "Dismantle" option to extract the components.' }] },
  "brilliant eidolon shard": { name: "Brilliant Eidolon Shard", url: "https://wiki.warframe.com/w/Brilliant_Eidolon_Shard", revid: 2815516, fetched: "2026-10-03T20:35:15.619135Z", drops: [], otherSections: [{ heading: "Acquisition", text: "Eidolon Teralysts and Eidolon Gantulysts will drop one Brilliant Eidolon Shard when captured at its final stage with a charged Eidolon Lure. Eidolon Hydrolysts will drop two Brilliant Eidolon Shards when captured at its final stage with a charged Eidolon Lure." }, { heading: "Acquisition", text: "* Eidolon Teralysts and Eidolon Gantulysts will drop one Brilliant Eidolon Shard when captured at its final stage with a charged Eidolon Lure." }] },
  "bronco incarnon genesis": { name: "Bronco Incarnon Genesis", url: "https://wiki.warframe.com/w/Bronco_Incarnon_Genesis", revid: 2814457, fetched: "2026-10-03T20:35:15.619135Z", foundText: "Purchased from Cavalero for 120 Platinum, complete with the resources used in its installation.", drops: [], otherSections: [{ heading: "Acquisition", text: "Upon completion of The Duviri Paradox and Angels of the Zariman, and unlocking The Steel Path, players can earn Bronco Incarnon Genesis from The Circuit's Steel Path to place on their Bronco with the help of Cavalero in the Chrysalith. This Incarnon Genesis form grants it evolutions to a transformation and newfound strength. Purchased from Cavalero for 120 Platinum, complete with the resources used in its installation. This purchase can only be made once." }, { heading: "Acquisition", text: "*Upon completion of The Duviri Paradox and Angels of the Zariman, and unlocking The Steel Path, players can earn Bronco Incarnon Genesis from The Circuit's Steel Path to place on their Bronco with the help of Cavalero in the Chrysalith. This Incarnon Genesis form grants it evolutions to a transformation and newfound strength." }] },
