  "curse of hearing": { name: "Curse of Hearing", url: "https://wiki.warframe.com/w/Curse_of_Hearing", revid: 2775085, fetched: "2026-10-03T20:35:15.619135Z", drops: [], otherSections: [{ heading: "Acquisition", text: "Defeating The Fragmented Zelator boss in Effervo, Deimos during the Operation; which will drop 1 Curse of Hearing, or 2 on Steel Path. Defeating The Fragmented One superboss in Effervo, Deimos during the Operation; which will drop 2 Curse of Hearing." }] },
