  "debt-bond": { name: "Debt-Bond", url: "https://wiki.warframe.com/w/Debt-Bond", revid: 2808043, fetched: "2026-10-03T20:35:15.619135Z", foundText: "Debt-bonds may be acquired from finishing Bounties in Orb Vallis as part of the common reward pools.", drops: [], otherSections: [{ heading: "Bounties", text: "Debt-bonds may be acquired from finishing Bounties in Orb Vallis as part of the common reward pools. The following is the drop table for each Debt-Bonds, as well as the bounties they are obtainable from. Debt-Bond Stage 1 Stage 2 Stage 3 Stage 4 Stage 5 Training Debt-Bond x2 Bounty 1 0% 20.00% 20.00% 19.33% 46.00% Shelter Debt-Bond x2 Bounty 2 0% 20.00% 20.00% 17.65% 37.50% Medical Debt-Bond x2 Bounty 3 0% 20.00% 20.00% 17.65% 37.50% Advances Debt-Bond x2 Bounty 4 0% 20.00% 20.00% 16.67% 33.33% Familial Debt-Bond x2 Bounty 5 0% 20.00% 20.00% 16.67% 33.33% Steel Path 0% 20.00% 20.00% 16.67% 33.33%" }, { heading: "Bounties", text: "Debt-bonds may be acquired from finishing Bounties in Orb Vallis as part of the common reward pools. The following is the drop table for each Debt-Bonds, as well as the bounties they are obtainable from." }] },
  "dendrite blastoma": { name: "Dendrite Blastoma", url: "https://wiki.warframe.com/w/Dendrite_Blastoma", revid: 2711779, fetched: "2026-10-03T20:35:15.619135Z", foundText: "Dendrite Blastoma are a resource that can be obtained by filleting Deimos fish.", drops: [], otherSections: [{ heading: "Acquisition", text: 'Dendrite Blastoma can be obtained by filleting Barbisteo and Vitreospina (both from the Cambion Drift ) at Daughter in the Necralisk. Dendrite Blastoma can also be bought from Daughter from the "Daily Special" in exchange for Platinum. Please note that the "Daily Special" wares are rotating, and Dendrite Blastoma may not be available. Dendrite Blastoma may also be acquired through rare Spitya Infested Cysts on the Cambion Drift.' }, { heading: "Acquisition", text: "* Dendrite Blastoma can be obtained by filleting Barbisteo and Vitreospina (both from the Cambion Drift) at Daughter in the Necralisk." }] },
  "dera incarnon genesis": { name: "Dera Incarnon Genesis", url: "https://wiki.warframe.com/w/Dera_Incarnon_Genesis", revid: 2814444, fetched: "2026-10-03T20:35:15.619135Z", foundText: "Purchased from Cavalero for 120 Platinum, complete with the resources used in its installation.", drops: [], otherSections: [{ heading: "Acquisition", text: "Upon completion of The Duviri Paradox and Angels of the Zariman, and unlocking The Steel Path, players can earn Dera Incarnon Genesis from The Circuit's Steel Path to place on their Dera with the help of Cavalero in the Chrysalith. This Incarnon Genesis form grants it evolutions to a transformation and newfound strength. Purchased from Cavalero for 120 Platinum, complete with the resources used in its installation. This purchase can only be made once." }, { heading: "Acquisition", text: "*Upon completion of The Duviri Paradox and Angels of the Zariman, and unlocking The Steel Path, players can earn Dera Incarnon Genesis from The Circuit's Steel Path to place on their Dera with the help of Cavalero in the Chrysalith. This Incarnon Genesis form grants it evolutions to a transformation and newfound strength." }] },
