  "devil's cap": { name: "Devil's Cap", url: "https://wiki.warframe.com/w/Devil's_Cap", revid: 2804619, fetched: "2026-10-03T20:35:15.619135Z", drops: [], otherSections: [{ heading: "Acquisition", text: "Devil's Cap can be harvested in the Deepmines Labs of the Critter Liberation Deepmines Bounty. May be awarded randomly as a bonus bounty reward at the end of the mission, appearing just beside the extraction elevator. Can be purchased for 10 Fergolyte from Nightcap at Rank 0 - Neutral. Deepmines Lab (Stage 2-5 zone in Critter Liberation bounty) Thunder-Button Weapons inflict Electricity Damage. The player's movement speed and melee attack speed increases, as if under the effects of Speed. Devil's Cap Weapons inflict Slash Damage. The player's eyes glow bright red. Damaging enemies will cosmetically sever limbs and create additional blood and gore effects. Weapons inflict Magnetic Damage. Player is followed by a group of Sprodlings that match their Warframe's colors. Vomval Trumpet Weapons inflict Tau Damage. Spawns a false Eidolon Vomvalyst that floats near the player." }, { heading: "Acquisition", text: "* can be harvested in the Deepmines Labs of the Critter Liberation Deepmines Bounty." }] },
  "devolved namalon": { name: "Devolved Namalon", url: "https://wiki.warframe.com/w/Devolved_Namalon", revid: 2768250, fetched: "2026-10-03T20:35:15.619135Z", drops: [], otherSections: [{ heading: "Acquisition", text: "The reusable blueprint can be purchased from Otak for 2,000 Standing, requiring Rank 1 - Stranger with the Entrati." }] },
  "diluted thermia": { name: "Diluted Thermia", url: "https://wiki.warframe.com/w/Diluted_Thermia", revid: 2779199, fetched: "2026-10-03T20:35:15.619135Z", foundText: "Thermia can be found fracturing the surface of the Orb Vallis during thermal flare-ups.", drops: [], otherSections: [{ heading: "Acquisition", text: "Diluted Thermia is obtained by successfully closing Thermia fractures in the Orb Vallis during the event. It is obtained every time a player or their squad close 4 Thermia fractures using the same coolant canister, or by using 4 coolant canisters at once in a single fracture, which will yield one Diluted Thermia, affected by resource boosters and double-resource events but not affected by resource drop chance boosters. Said canister will then disappear, and the players will have to search for a new one if they want to continue closing fractures." }] },
  dirac: { name: "Dirac", url: "https://wiki.warframe.com/w/Dirac", revid: 2710507, fetched: "2026-10-03T20:35:15.619135Z", foundText: "Dirac can be found throughout Empyrean missions either as rare environmental drops or as end-of-mission bonus reward. Can be directly purchased in 400/1000 bundles in the Market for Platinum.", drops: [], otherSections: [{ heading: "Acquisition", text: "Dirac can be found throughout Empyrean missions either as rare environmental drops or as end-of-mission bonus reward. Scrapping duplicate or unwanted Railjack wreckage modules. For MkI/MkII/MkIII you get 75/150/225 Dirac respectively. Scrapping duplicate or unwanted Avionics. Can be directly purchased in 400/1000 bundles in the Market for Platinum." }, { heading: "Acquisition", text: "*Dirac can be found throughout Empyrean missions either as rare environmental drops or as end-of-mission bonus reward." }] },
