  "dread incarnon genesis": { name: "Dread Incarnon Genesis", url: "https://wiki.warframe.com/w/Dread_Incarnon_Genesis", revid: 2814445, fetched: "2026-10-03T20:35:15.619135Z", foundText: "Purchased from Cavalero for 120 Platinum, complete with the resources used in its installation.", drops: [], otherSections: [{ heading: "Acquisition", text: "Upon completion of The Duviri Paradox and Angels of the Zariman, and unlocking The Steel Path, players can earn Dread Incarnon Genesis from The Circuit's Steel Path to place on their Dread with the help of Cavalero in the Chrysalith. This Incarnon Genesis form grants it evolutions to a transformation and newfound strength. Purchased from Cavalero for 120 Platinum, complete with the resources used in its installation. This purchase can only be made once." }, { heading: "Acquisition", text: "*Upon completion of The Duviri Paradox and Angels of the Zariman, and unlocking The Steel Path, players can earn Dread Incarnon Genesis from The Circuit's Steel Path to place on their Dread with the help of Cavalero in the Chrysalith. This Incarnon Genesis form grants it evolutions to a transformation and newfound strength." }] },
  "dual ichor incarnon genesis": { name: "Dual Ichor Incarnon Genesis", url: "https://wiki.warframe.com/w/Dual_Ichor_Incarnon_Genesis", revid: 2812453, fetched: "2026-10-03T20:35:15.619135Z", foundText: "Purchased from Cavalero for 120 Platinum, complete with the resources used in its installation.", drops: [], otherSections: [{ heading: "Acquisition", text: "Upon completion of The Duviri Paradox and Angels of the Zariman, and unlocking The Steel Path, players can earn Dual Ichor Incarnon Genesis from The Circuit's Steel Path to place on their Dual Ichor with the help of Cavalero in the Chrysalith. This Incarnon Genesis form grants it evolutions to a transformation and newfound strength. Purchased from Cavalero for 120 Platinum, complete with the resources used in its installation. This purchase can only be made once." }, { heading: "Acquisition", text: "*Upon completion of The Duviri Paradox and Angels of the Zariman, and unlocking The Steel Path, players can earn Dual Ichor Incarnon Genesis from The Circuit's Steel Path to place on their Dual Ichor with the help of Cavalero in the Chrysalith. This Incarnon Genesis form grants it evolutions to a transformation and newfound strength." }] },
  "dual toxocyst incarnon genesis": { name: "Dual Toxocyst Incarnon Genesis", url: "https://wiki.warframe.com/w/Dual_Toxocyst_Incarnon_Genesis", revid: 2814460, fetched: "2026-10-03T20:35:15.619135Z", foundText: "Purchased from Cavalero for 120 Platinum, complete with the resources used in its installation.", drops: [], otherSections: [{ heading: "Acquisition", text: "Upon completion of The Duviri Paradox and Angels of the Zariman, and unlocking The Steel Path, players can earn Dual Toxocyst Incarnon Genesis from The Circuit's Steel Path to place on their Dual Toxocyst with the help of Cavalero in the Chrysalith. This Incarnon Genesis form grants it evolutions to a transformation and newfound strength. Purchased from Cavalero for 120 Platinum, complete with the resources used in its installation. This purchase can only be made once." }, { heading: "Acquisition", text: "*Upon completion of The Duviri Paradox and Angels of the Zariman, and unlocking The Steel Path, players can earn Dual Toxocyst Incarnon Genesis from The Circuit's Steel Path to place on their Dual Toxocyst with the help of Cavalero in the Chrysalith. This Incarnon Genesis form grants it evolutions to a transformation and newfound strength." }] },
  "dull button": { name: "Dull Button", url: "https://wiki.warframe.com/w/Dull_Button", revid: 2804638, fetched: "2026-10-03T20:35:15.619135Z", drops: [], otherSections: [{ heading: "Acquisition", text: "Dull Button can be harvested in the entrance caves of all Deepmines Bounties. May be awarded randomly as a bonus bounty reward at the end of the mission, appearing just beside the extraction elevator. Can be purchased for 10 Fergolyte from Nightcap at Rank 0 - Neutral. Deepmines Caves (Stage 1 zone in all bounties) Muck Bonnet Weapons inflict Toxin Damage. Reeking Puffball Weapons inflict Gas Damage. Player is surrounded by cloudy green effects. Dull Button Clears existing Mushroom effects. Violet's Bane Weapons inflict Viral Damage. Spawns four Clems that follow the player, but their gunfire will harmlessly phase through enemies." }, { heading: "Acquisition", text: "* can be harvested in the entrance caves of all Deepmines Bounties." }] },
  "dusklight sarracenia": { name: "Dusklight Sarracenia", url: "https://wiki.warframe.com/w/Dusklight_Sarracenia", revid: 2805233, fetched: "2026-10-03T20:35:15.619135Z", foundText: "Dusklight Sarracenias are Plants found only in Grineer Shipyards, which are most commonly found on Ceres within pools of toxic waste.", drops: [], otherSections: [] },
  "echo voca": { name: "Echo Voca", url: "https://wiki.warframe.com/w/Echo_Voca", revid: 2728983, fetched: "2026-10-03T20:35:15.619135Z", drops: [{ missionType: "Sanctum Anatomica Bounty", source: "Sanctum Anatomica Bounty 115-120", rotationOrTable: "A", chance: 0.1471, quantity: 1, nodes: ["Sanctum Anatomica, Deimos; talk to Fibonacci"] }], otherSections: [{ heading: "Acquisition", text: "Echo Voca can be found scattered across any Albrecht's Laboratories mission as an interactable pickup. Killing Gruzzlings have a chance to leave Echo Voca pickups. Tier 5 Bounties from Fibonacci have a chance to award an Echo Voca. Every 8 hours, one Echo Voca can be purchased from Loid using resources found in the Albrecht's Laboratories." }, { heading: "Enemy Drop Tables", text: "Drop Table Chance [ 4 ] Item Chance [ 1 ] Chance [ 5 ] Expected Kills [ 6 ] Quantity [ 2 ] Avg. Per roll attempt [ 7 ] No enemy drop tables with this item Sourced from the official drop table repository. See Module:DropTables/data to edit on the wiki." }, { heading: "Acquisition", text: "*Echo Voca can be found scattered across any Albrecht's Laboratories mission as an interactable pickup." }] },
  "echowinder anoscopic sensor": { name: "Echowinder Anoscopic Sensor", url: "https://wiki.warframe.com/w/Echowinder_Anoscopic_Sensor", revid: 2711730, fetched: "2026-10-03T20:35:15.619135Z", foundText: "Anoscopic Sensor is a Resource extracted from Echowinder, a Servofish found in lakes during warm weather in Orb Vallis.", drops: [], otherSections: [{ heading: "Acquisition", text: 'Anoscopic Sensors are acquired by dismantling Echowinders caught through Fishing. Go to The Business in Fortuna, select the desired amount of Echowinders available, and select the " Dismantle " option to extract the components. Each Echowinder yields one Anoscopic Sensor.' }, { heading: "Acquisition", text: 'Anoscopic Sensors are acquired by dismantling Echowinders caught through Fishing. Go to The Business in Fortuna, select the desired amount of Echowinders available, and select the "Dismantle" option to extract the components.' }] },
