  "eidolon shard": { name: "Eidolon Shard", url: "https://wiki.warframe.com/w/Eidolon_Shard", revid: 2815520, fetched: "2026-10-03T20:35:15.619135Z", foundText: "A decorative replica of an Eidolon Shard (called the Eidolon Relic) can be purchased from the Quills at Rank 4 (Instrument) for 50,000 Standing standing.", drops: [], otherSections: [{ heading: "Acquisition", text: "The Eidolon Teralyst, Gantulyst, and Hydrolyst will drop one, three, and five Eidolon Shards respectively regardless of whether they are killed or captured." }] },
