  "furax incarnon genesis": { name: "Furax Incarnon Genesis", url: "https://wiki.warframe.com/w/Furax_Incarnon_Genesis", revid: 2814583, fetched: "2026-10-03T20:35:15.619135Z", foundText: "Purchased from Cavalero for 120 Platinum, complete with the resources used in its installation.", drops: [], otherSections: [{ heading: "Acquisition", text: "Upon completion of The Duviri Paradox and Angels of the Zariman, and unlocking The Steel Path, players can earn Furax Incarnon Genesis from The Circuit's Steel Path to place on their Furax with the help of Cavalero in the Chrysalith. This Incarnon Genesis form grants it evolutions to a transformation and newfound strength. Purchased from Cavalero for 120 Platinum, complete with the resources used in its installation. This purchase can only be made once." }, { heading: "Acquisition", text: "*Upon completion of The Duviri Paradox and Angels of the Zariman, and unlocking The Steel Path, players can earn Furax Incarnon Genesis from The Circuit's Steel Path to place on their Furax with the help of Cavalero in the Chrysalith. This Incarnon Genesis form grants it evolutions to a transformation and newfound strength." }] },
  "furis incarnon genesis": { name: "Furis Incarnon Genesis", url: "https://wiki.warframe.com/w/Furis_Incarnon_Genesis", revid: 2814461, fetched: "2026-10-03T20:35:15.619135Z", foundText: "Purchased from Cavalero for 120 Platinum, complete with the resources used in its installation.", drops: [], otherSections: [{ heading: "Acquisition", text: "Upon completion of The Duviri Paradox and Angels of the Zariman, and unlocking The Steel Path, players can earn Furis Incarnon Genesis from The Circuit's Steel Path to place on their Furis with the help of Cavalero in the Chrysalith. This Incarnon Genesis form grants it evolutions to a transformation and newfound strength. Purchased from Cavalero for 120 Platinum, complete with the resources used in its installation. This purchase can only be made once." }, { heading: "Acquisition", text: "This Incarnon Genesis form grants it evolutions to a transformation and newfound strength." }] },
