  "gorgaricus spore": { name: "Gorgaricus Spore", url: "https://wiki.warframe.com/w/Gorgaricus_Spore", revid: 2794775, fetched: "2026-10-03T20:35:15.619135Z", foundText: "Gorgaricus Spore is resource that can be found all over Orb Vallis, being purple sacs that can be found hanging beneath the caps of the giant mushrooms. Mature Gorgaricus Sacs are purple in contrast to the immature, orange sacs growing with them, and are harvested by attacking the sacs and letting them fall to the ground. Gorgaricus Spores are also rewarded from Bounties, or from resource containers all over the Vallis.", drops: [{ missionType: "Deepmines Bounty", source: "Nokko: Weed The Gardens Rewards", rotationOrTable: "B", chance: 0.3, quantity: 20, nodes: ["Fortuna, Venus; talk to Nightcap; Must complete The New War quest"] }, { missionType: "Fortuna Bounty", source: "Fortuna Bounty Lvl 10-30 Stage 1", rotationOrTable: "C", chance: 0.25, quantity: 15, nodes: ["Orb Vallis/Fortuna, Venus; talk to Eudico"] }, { missionType: "Fortuna Bounty", source: "Fortuna Bounty Lvl 5-15 Stage 2", rotationOrTable: "C", chance: 0.15, quantity: 5, nodes: ["Orb Vallis/Fortuna, Venus; talk to Eudico"] }, { missionType: "Fortuna Bounty", source: "Fortuna Bounty Lvl 10-30 Stage 2", rotationOrTable: "C", chance: 0.15, quantity: 15, nodes: ["Orb Vallis/Fortuna, Venus; talk to Eudico"] }, { missionType: "Fortuna Bounty", source: "Fortuna Bounty Lvl 5-15 Stage 1", rotationOrTable: "C", chance: 0.25, quantity: 5, nodes: ["Orb Vallis/Fortuna, Venus; talk to Eudico"] }], otherSections: [{ heading: "Enemy Drop Tables", text: "Drop Table Chance [ 4 ] Item Chance [ 1 ] Chance [ 5 ] Expected Kills [ 6 ] Quantity [ 2 ] Avg. Per roll attempt [ 7 ] No enemy drop tables with this item Sourced from the official drop table repository. See Module:DropTables/data to edit on the wiki." }] },
  "gorgon incarnon genesis": { name: "Gorgon Incarnon Genesis", url: "https://wiki.warframe.com/w/Gorgon_Incarnon_Genesis", revid: 2814446, fetched: "2026-10-03T20:35:15.619135Z", foundText: "Purchased from Cavalero for 120 Platinum, complete with the resources used in its installation.", drops: [], otherSections: [{ heading: "Acquisition", text: "Upon completion of The Duviri Paradox and Angels of the Zariman, and unlocking The Steel Path, players can earn Gorgon Incarnon Genesis from The Circuit's Steel Path to place on their Gorgon with the help of Cavalero in the Chrysalith. This Incarnon Genesis form grants it evolutions to a transformation and newfound strength. Purchased from Cavalero for 120 Platinum, complete with the resources used in its installation. This purchase can only be made once." }, { heading: "Acquisition", text: "*Upon completion of The Duviri Paradox and Angels of the Zariman, and unlocking The Steel Path, players can earn Gorgon Incarnon Genesis from The Circuit's Steel Path to place on their Gorgon with the help of Cavalero in the Chrysalith. This Incarnon Genesis form grants it evolutions to a transformation and newfound strength." }] },
