  "live heartcell": { name: "Live Heartcell", url: "https://wiki.warframe.com/w/Live_Heartcell", revid: 2802644, fetched: "2026-10-03T20:35:15.619135Z", foundText: "Live Heartcell are a rare resource found in H\xF6llvania. They are obtained through activities surrounding the Technocyte Coda.", drops: [], otherSections: [{ heading: "Drop Locations", text: "10-15 are earned from vanquishing a Technocyte Coda. 1 per Technocyte Coda defeated past the first in the Technocyte Coda Concert, regardless of vanquish or convert, up to 3 in a full squad. 10% chance from a Parazon Mercy on a Technocyte Coda Duet with Quick Correct mod equipped." }, { heading: "Drop Locations", text: "*10-15 are earned from vanquishing a Technocyte Coda." }] },
