  "lua lens": { name: "Lua Lens", url: "https://wiki.warframe.com/w/Lua_Lens", revid: 2797097, fetched: "2026-10-03T20:35:15.619135Z", foundText: "Their blueprint can be acquired as a Rotation C Lua Disruption reward or traded between players.", drops: [], otherSections: [{ heading: "Acquisition", text: "Their blueprint can be acquired as a Rotation C Lua Disruption reward or traded between players. Lua Lenses require an Eidolon Focus Lens from any of the 5 Focus Schools to craft. Manufacturing Requirements 25,000 1 5 Time: 24 hrs Rush: 10 Platinum Market Price: 120 Blueprints Price: N/A" }, { heading: "Drop Locations", text: "Mission Type Drop Table Chance [ 1 ] Quantity [ 2 ] Avg. Per roll [ 3 ] Star Chart Nodes Lua Disruption C 8.05% 1 0.0805 Apollo, Lua Sourced from the official drop table repository. See Module:DropTables/data to edit on the wiki." }, { heading: "Acquisition", text: "Their blueprint can be acquired as a Rotation C Lua Disruption reward or traded between players. Lua Lenses require an Eidolon Focus Lens from any of the 5 Focus Schools to craft." }] },
  "lua thrax plasm": { name: "Lua Thrax Plasm", url: "https://wiki.warframe.com/w/Lua_Thrax_Plasm", revid: 2815504, fetched: "2026-10-03T20:35:15.619135Z", drops: [], otherSections: [{ heading: "Acquisition", text: "Guaranteed Rotation reward from Conjunction Survival. Dropped by Hollow Thrax Centurion, Eclipse Thrax Centurion, Hollow Thrax Legatus, and Lua Thrax Legatus that appear after each Rotation in Conjunction Survival at a 30% chance. Source [ 1 ] Lua Thrax Plasm Nearly Guaranteed Yuvarium (Lv 25-30 Conjunction Survival ) 3 100% 1 1 Circulus (Lv 80-100 Conjunction Survival) 5 The Steel Path Yuvarium (Lv 125-130 Conjunction Survival) The Steel Path Circulus (Lv 180-200 Conjunction Survival) 6 Hollow Thrax Centurion 1 30% 3 \u2013 4 19 \xB1 6 Eclipse Thrax Centurion 1 30% 3 \u2013 4 19 \xB1 6 Hollow Thrax Legatus 1 30% 3 \u2013 4 19 \xB1 6 Lua Thrax Legatus 1 30% 3 \u2013 4 19 \xB1 6" }] },
  "lucent teroglobe": { name: "Lucent Teroglobe", url: "https://wiki.warframe.com/w/Lucent_Teroglobe", revid: 2711767, fetched: "2026-10-03T20:35:15.619135Z", foundText: "Lucent Teroglobe is a resource found in the Cambion Drift. They can be retrieved from Vitrific Outcrops, which appear around certain points of interests such as Requiem Obelisks located on the surface, and may also be rewarded from completing Bounties.", drops: [{ missionType: "Necralisk Bounty", source: "Necralisk Bounty Lvl 5-15 Stage 2", rotationOrTable: "C", chance: 0.2581, quantity: 15, nodes: ["Cambion Drift/Necralisk, Deimos; talk to Mother"] }, { missionType: "Necralisk Bounty", source: "Necralisk Bounty Lvl 5-15 Stage 1", rotationOrTable: "C", chance: 0.3333, quantity: 15, nodes: ["Cambion Drift/Necralisk, Deimos; talk to Mother"] }], otherSections: [{ heading: "Enemy Drop Tables", text: "Drop Table Chance [ 4 ] Item Chance [ 1 ] Chance [ 5 ] Expected Kills [ 6 ] Quantity [ 2 ] Avg. Per roll attempt [ 7 ] No enemy drop tables with this item Sourced from the official drop table repository. See Module:DropTables/data to edit on the wiki." }] },
