  "lyroic bridge": { name: "Lyroic Bridge", url: "https://wiki.warframe.com/w/Lyroic_Bridge", revid: 2791350, fetched: "2026-10-03T20:35:15.619135Z", foundText: 'Lyroic Bridge is a special resource that can be obtained from the "Recall: Hunhullus" mission in The Perita Rebellion.', drops: [], otherSections: [{ heading: "Acquisition", text: '75 Lyroic Bridge is awarded upon completion of The Old Peace quest. Every Order completed in the Recall: Hunhullus awards 1 Lyroic Bridge. Defeating the Hunhullus awards 10 Lyroic Bridge. In The Steel Path, defeating Commandeered Warframes (outside of the Prime Vanguard fight) may drop 2 Lyroic Bridge, regardless of the Recall mission. Not affected by Resource booster. Can be bought from Marie Leroux in La Cath\xE9drale, Sanctum Anatomica, in quantities of 15 in exchange for Agnovidisc, Laudavi, and/or Servoris. These purchases are limited to one per day, and are on a rotating basis. Can be bought from the Market as part of the Tektolyst Artifact Acquisition Pack, in quantities of 150 for 175 Platinum. This bundle can only be purchased once. 10 Lyroic Bridge can be obtained from the mission " The Guilty " ( Hardmode Boss ) in The Perita Rebellion, as a repeated mission clearing reward.' }, { heading: "Acquisition", text: "*75 Lyroic Bridge is awarded upon completion of The Old Peace quest." }] },
  "magistar incarnon genesis": { name: "Magistar Incarnon Genesis", url: "https://wiki.warframe.com/w/Magistar_Incarnon_Genesis", revid: 2773442, fetched: "2026-10-03T20:35:15.619135Z", foundText: "Purchased from Cavalero for 120 Platinum, complete with the resources used in its installation.", drops: [], otherSections: [{ heading: "Acquisition", text: "Upon completion of The Duviri Paradox and Angels of the Zariman, and unlocking The Steel Path, players can earn Magistar Incarnon Genesis from The Circuit's Steel Path to place on their Magistar with the help of Cavalero in the Chrysalith. This Incarnon Genesis form grants it evolutions to a transformation and newfound strength. Purchased from Cavalero for 120 Platinum, complete with the resources used in its installation. This purchase can only be made once." }, { heading: "Acquisition", text: "*Upon completion of The Duviri Paradox and Angels of the Zariman, and unlocking The Steel Path, players can earn Magistar Incarnon Genesis from The Circuit's Steel Path to place on their Magistar with the help of Cavalero in the Chrysalith. This Incarnon Genesis form grants it evolutions to a transformation and newfound strength." }] },
  maphica: { name: "Maphica", url: "https://wiki.warframe.com/w/Maphica", revid: 2814474, fetched: "2026-10-03T20:35:15.619135Z", foundText: "Dropped from Storage Containers.", drops: [], otherSections: [{ heading: "Acquisition", text: "Potentially awarded in quantities of 5 on Infernums 2, 4, 9, 11, 16, and 18. Potentially awarded in quantities of 15 on Infernums 2, 9, and 16 on The Steel Path. Dropped from Storage Containers. Drops are not affected by Resource Booster or Loyal Retriever / Resourceful Retriever. Can be bought from Marie Leroux in La Cath\xE9drale, Sanctum Anatomica, in quantities of 10 in exchange for Agnovidisc, Laudavi, and/or Servoris. These purchases are limited to one per day." }] },
