  "melee arcane adapter": { name: "Melee Arcane Adapter", url: "https://wiki.warframe.com/w/Melee_Arcane_Adapter", revid: 2790895, fetched: "2026-10-03T20:35:15.619135Z", foundText: "Can be purchased from Bird 3 for 50,000 Standing requiring Rank 3 - Colleague with Cavia. Can be purchased from the Market for 20 Platinum. Can be rewarded from The Descendia after clearing Infernum 21.", drops: [{ missionType: "Deep Archimedea", source: "Deep Archimedea", rotationOrTable: "B", chance: 0.05, quantity: 1, nodes: ["Sanctum Anatomica, Deimos; Must complete Whispers in the Walls quest and being Rank 5: Illuminate with the Cavia."] }, { missionType: "Deep Archimedea", source: "Deep Archimedea", rotationOrTable: "A", chance: 0.15, quantity: 1, nodes: ["Sanctum Anatomica, Deimos; Must complete Whispers in the Walls quest and being Rank 5: Illuminate with the Cavia."] }, { missionType: "Netracells", source: "Netracells", rotationOrTable: "A", chance: 0.15, quantity: 1, nodes: ["Testudo, Deimos"] }], otherSections: [{ heading: "Acquisition", text: "Can be awarded from Netracell missions. Can be awarded from Deep Archimedea missions. Can be purchased from the Market for 20 Platinum. Will not appear until the player has completed the Whispers in the Walls quest. (may not always be available due to randomized weekly awards) Can be rewarded from The Descendia after clearing Infernum 21. (may not always be available due to randomized weekly awards)" }, { heading: "Enemy Drop Tables", text: "Drop Table Chance [ 4 ] Item Chance [ 1 ] Chance [ 5 ] Expected Kills [ 6 ] Quantity [ 2 ] Avg. Per roll attempt [ 7 ] No enemy drop tables with this item Sourced from the official drop table repository. See Module:DropTables/data to edit on the wiki." }, { heading: "Acquisition", text: "*Can be purchased from Bird 3 for 50,000 Standing requiring Rank 3 - Colleague with Cavia." }] },
  mining: { name: "Mining", url: "https://wiki.warframe.com/w/Mining", revid: 2814050, fetched: "2026-10-03T20:35:15.619135Z", foundText: "The Sunpoint Plasma Drill is superior to the Nosam Cutters: it can mine Very Rare gems, includes the features of other Cutters, can be upgraded, and can be purchased earlier than most other Cutters as it does not require any Syndicate ranks.", drops: [], otherSections: [{ heading: "Gear Acquisition", text: "Before players can begin mining, they must first acquire a Nosam Cutter from Old Man Suumbaat in Cetus for Ostron standing, or a Sunpoint Plasma Drill from Smokefinger in Fortuna for Solaris United standing. Players must then equip the mining tool in their Gear Wheel to use it. The Sunpoint Plasma Drill is superior to the Nosam Cutters: it can mine Very Rare gems, includes the features of other Cutters, can be upgraded, and can be purchased earlier than most other Cutters as it does not require any Syndicate ranks. It also has the slowest drill progress, making precise timing easier. It does, however, require at least 2,500 with Solaris United to be able to purchase, which could involve multiple Bounty Missions. Acquiring a Basic Nosam Cutter in Cetus for a much simpler 500 (low enough to be gained during Saya's Vigil ) and mining Venus gems that can be traded in for Standing is a quick way to get the Sunpoint Plasma Drill. Note that a Nosam Cutter and a Sunpoint Plasma Drill cannot be equipped at the same time." }, { heading: "Gear Acquisition", text: "Before players can begin mining, they must first acquire a Nosam Cutter from Old Man Suumbaat in Cetus for Ostron standing, or a Sunpoint Plasma Drill from Smokefinger in Fortuna for Solaris United standing. Players must then equip the mining tool in their Gear Wheel to use it." }] },
  "mirewinder parallel biode": { name: "Mirewinder Parallel Biode", url: "https://wiki.warframe.com/w/Mirewinder_Parallel_Biode", revid: 2711721, fetched: "2026-10-03T20:35:15.619135Z", foundText: "Mirewinder Parallel Biode is a Resource extracted from Mirewinder, a Servofish found in caves in Orb Vallis.", drops: [], otherSections: [{ heading: "Acquisition", text: 'Parallel Biodes are acquired by dismantling Mirewinders caught through Fishing. Go to The Business in Fortuna, select the desired amount of Mirewinders available, and select the " Dismantle " option to extract the components. Each Mirewinder yields one Parallel Biode. This resource also drops from containers in Orb Vallis.' }, { heading: "Acquisition", text: 'Parallel Biodes are acquired by dismantling Mirewinders caught through Fishing. Go to The Business in Fortuna, select the desired amount of Mirewinders available, and select the "Dismantle" option to extract the components.' }] },
  "miter incarnon genesis": { name: "Miter Incarnon Genesis", url: "https://wiki.warframe.com/w/Miter_Incarnon_Genesis", revid: 2814448, fetched: "2026-10-03T20:35:15.619135Z", foundText: "Purchased from Cavalero for 120 Platinum, complete with the resources used in its installation.", drops: [], otherSections: [{ heading: "Acquisition", text: "Upon completion of The Duviri Paradox and Angels of the Zariman, and unlocking The Steel Path, players can earn Miter Incarnon Genesis from The Circuit's Steel Path to place on their Miter with the help of Cavalero in the Chrysalith. This Incarnon Genesis form grants it evolutions to a transformation and newfound strength. Purchased from Cavalero for 120 Platinum, complete with the resources used in its installation. This purchase can only be made once." }, { heading: "Acquisition", text: "*Upon completion of The Duviri Paradox and Angels of the Zariman, and unlocking The Steel Path, players can earn Miter Incarnon Genesis from The Circuit's Steel Path to place on their Miter with the help of Cavalero in the Chrysalith. This Incarnon Genesis form grants it evolutions to a transformation and newfound strength." }] },
  "mod drop chance booster": { name: "Mod Drop Chance Booster", url: "https://wiki.warframe.com/w/Mod_Drop_Chance_Booster", revid: 2815614, fetched: "2026-10-03T20:35:15.619135Z", foundText: "A 1-day booster can be obtained as a reward from the Void Surplus offering for sale by Baro Ki'Teer.", drops: [{ missionType: "Archon Hunt", source: "Archon Hunt", rotationOrTable: "A", chance: 0.0327, quantity: 1, nodes: ["See in-game World State Window, must complete Veilbreaker quest"] }, { missionType: "Sortie", source: "Sortie", rotationOrTable: "A", chance: 0.0327, quantity: 1, nodes: ["See in-game World State Window"] }], otherSections: [{ heading: "Enemy Drop Tables", text: "Drop Table Chance [ 4 ] Item Chance [ 1 ] Chance [ 5 ] Expected Kills [ 6 ] Quantity [ 2 ] Avg. Per roll attempt [ 7 ] No enemy drop tables with this item Sourced from the official drop table repository. See Module:DropTables/data to edit on the wiki. A 1-day booster can be obtained as a reward from the Void Surplus offering for sale by Baro Ki'Teer." }] },
