  "necramech summon": { name: "Necramech Summon", url: "https://wiki.warframe.com/w/Necramech_Summon", revid: 2620955, fetched: "2026-10-03T20:35:15.619135Z", foundText: "A Necramech Summon is automatically acquired after the player builds their first Necramech.", drops: [], otherSections: [{ heading: "Acquisition", text: "A Necramech Summon is automatically acquired after the player builds their first Necramech. However, the item can only be equipped in the Gear wheel after the player has completed The War Within." }] },
