  "obex incarnon genesis": { name: "Obex Incarnon Genesis", url: "https://wiki.warframe.com/w/Obex_Incarnon_Genesis", revid: 2803254, fetched: "2026-10-03T20:35:15.619135Z", foundText: "Purchased from Cavalero for 120 Platinum, complete with the resources used in its installation.", drops: [], otherSections: [{ heading: "Acquisition", text: "Upon completion of The Duviri Paradox and Angels of the Zariman, and unlocking The Steel Path, players can earn Obex Incarnon Genesis from The Circuit's Steel Path to place on their Obex with the help of Cavalero in the Chrysalith. This Incarnon Genesis form grants it evolutions to a transformation and newfound strength. Purchased from Cavalero for 120 Platinum, complete with the resources used in its installation. This purchase can only be made once." }, { heading: "Acquisition", text: "*Upon completion of The Duviri Paradox and Angels of the Zariman, and unlocking The Steel Path, players can earn Obex Incarnon Genesis from The Circuit's Steel Path to place on their Obex with the help of Cavalero in the Chrysalith. This Incarnon Genesis form grants it evolutions to a transformation and newfound strength." }] },
  "ocular stem-root": { name: "Ocular Stem-Root", url: "https://wiki.warframe.com/w/Ocular_Stem-Root", revid: 2711778, fetched: "2026-10-03T20:35:15.619135Z", foundText: "Ocular Stem-Roots are a resource that can be obtained by filleting the Flagellocanth from the Cambion Drift.", drops: [], otherSections: [{ heading: "Acquisition", text: 'Ocular Stem-Roots can be obtained by filleting Flagellocanth s through Daughter in the Necralisk. Ocular Stem-Roots can also be bought from Daughter from the "Daily Special" in exchange for Platinum. Note that the "Daily Special" wares are rotating, and Ocular Stem-Root may not be available. Ocular Stem-Roots can also be obtained through Isolation Vault bounties.' }, { heading: "Acquisition", text: "* Ocular Stem-Roots can be obtained by filleting Flagellocanths through Daughter in the Necralisk." }] },
