  "orokin cipher": { name: "Orokin Cipher", url: "https://wiki.warframe.com/w/Orokin_Cipher", revid: 2805258, fetched: "2026-10-03T20:35:15.619135Z", foundText: "One Orokin Cipher (along with a random Corrupted Mod) is obtained by opening an Orokin Vault in an Orokin Derelict tileset mission on Deimos.", drops: [], otherSections: [{ heading: "Acquisition", text: "One Orokin Cipher (along with a random Corrupted Mod ) is obtained by opening an Orokin Vault in an Orokin Derelict tileset mission on Deimos." }, { heading: "Acquisition", text: "One Orokin Cipher (along with a random Corrupted Mod) is obtained by opening an Orokin Vault in an Orokin Derelict tileset mission on Deimos." }] },
  "orokin ducats": { name: "Orokin Ducats", url: "https://wiki.warframe.com/w/Orokin_Ducats", revid: 2811844, fetched: "2026-10-03T20:35:15.619135Z", foundText: "Ducats can be acquired by selling Prime blueprints, Prime weapon parts, and crafted Prime Warframe components at the Void Trader's Kiosks found in the Concourse area in Relays (except Maroo's Bazaar). These Prime parts and blueprints, in turn, are acquired from Void Relics, or from trading with other players (note that Ducats themselves cannot be traded directly).", drops: [], otherSections: [{ heading: "Acquisition", text: "Ducats can be acquired by selling Prime blueprints, Prime weapon parts, and crafted Prime Warframe components at the Void Trader's Kiosks found in the Concourse area in Relays (except Maroo's Bazaar ). These Prime parts and blueprints, in turn, are acquired from Void Relics, or from trading with other players (note that Ducats themselves cannot be traded directly). Note that while accessing Baro Ki'Teer is time limited, the Void Trader's Kiosks can be accessed at any time. Ducats may also be purchased for Aya from Varzia during Prime Resurgence. Void Surplus have a 2.00% chance of containing 1,000 Ducats. Baro Ki'Teer sells one Void Surplus per visit for 50,000 Credits. The Ducats value depends on the item's rarity as it appears on the Void Relics that they originate from. To make up for the loss in rarity and thus value, such items are worth 25 and 65, respectively." }, { heading: "Acquisition", text: "Ducats can be acquired by selling Prime blueprints, Prime weapon parts, and crafted Prime Warframe components at the Void Trader's Kiosks found in the Concourse area in Relays (except Maroo's Bazaar). These Prime parts and blueprints, in turn, are acquired from Void Relics, or from trading with other players (note that Ducats themselves cannot be traded directly). Note that while accessing Baro Ki'Teer is time limited, the Void Trader's Kiosks can be accessed at any time." }] },
