  "recaster neural relay": { name: "Recaster Neural Relay", url: "https://wiki.warframe.com/w/Recaster_Neural_Relay", revid: 2711722, fetched: "2026-10-03T20:35:15.619135Z", foundText: "Recaster Neural Relay is a Resource extracted from Recaster, a Servofish found in Orb Vallis, in Fortuna pond hotspots during cold weather.", drops: [], otherSections: [{ heading: "Acquisition", text: 'Neural Relay is acquired by dismantling Recasters caught through Fishing. Go to The Business in Fortuna, select the desired amount of Recasters available, and select the " Dismantle " option to extract the components. Each Recaster yields one Neural Relay. This resource also drops from containers in Orb Vallis.' }, { heading: "Acquisition", text: 'Neural Relay is acquired by dismantling Recasters caught through Fishing. Go to The Business in Fortuna, select the desired amount of Recasters available, and select the "Dismantle" option to extract the components.' }] },
  "reeking puffball": { name: "Reeking Puffball", url: "https://wiki.warframe.com/w/Reeking_Puffball", revid: 2804631, fetched: "2026-10-03T20:35:15.619135Z", drops: [], otherSections: [{ heading: "Acquisition", text: "Reeking Puffball can be harvested in the entrance caves of all Deepmines Bounties. May be awarded randomly as a bonus bounty reward at the end of the mission, appearing just beside the extraction elevator. Can be purchased for 10 Fergolyte from Nightcap, requiring Rank 2 - Curious. Deepmines Caves (Stage 1 zone in all bounties) Muck Bonnet Weapons inflict Toxin Damage. Reeking Puffball Weapons inflict Gas Damage. Player is surrounded by cloudy green effects. Dull Button Clears existing Mushroom effects. Violet's Bane Weapons inflict Viral Damage. Spawns four Clems that follow the player, but their gunfire will harmlessly phase through enemies." }, { heading: "Acquisition", text: "* can be harvested in the entrance caves of all Deepmines Bounties." }] },
