  scrap: { name: "Scrap", url: "https://wiki.warframe.com/w/Scrap", revid: 2711731, fetched: "2026-10-03T20:35:15.619135Z", foundText: "Scrap can be acquired by dismantling Servofish at The Business in Fortuna.", drops: [], otherSections: [{ heading: "Acquisition", text: "Scrap can be acquired by dismantling Servofish at The Business in Fortuna. The yield is increased by how intricate the caught fish is. Eye-Eye 3 4 5 1 2 3 2 3 4 4 5 6 2 3 4 2 3 4 1 2 3 3 4 5 1 2 3 3 5 7 3 4 5 1 3 5 4 6 8" }, { heading: "Acquisition", text: "Scrap can be acquired by dismantling Servofish at The Business in Fortuna. The yield is increased by how intricate the caught fish is." }] },
  "scrubber exa brain": { name: "Scrubber Exa Brain", url: "https://wiki.warframe.com/w/Scrubber_Exa_Brain", revid: 2711726, fetched: "2026-10-03T20:35:15.619135Z", foundText: "Scrubber Exa Brain is a Resource extracted from the Scrubber, a Servofish found in caves during cold/warm weather in Orb Vallis.", drops: [], otherSections: [{ heading: "Acquisition", text: 'Exa Brains are acquired by dismantling Scrubbers caught through Fishing. Go to The Business in Fortuna, select the desired amount of Scrubbers available, and select the " Dismantle " option to extract the components. Each Scrubber yields one Exa Brain. Exa Brains can be found randomly in containers.' }, { heading: "Acquisition", text: 'Exa Brains are acquired by dismantling Scrubbers caught through Fishing. Go to The Business in Fortuna, select the desired amount of Scrubbers available, and select the "Dismantle" option to extract the components.' }] },
  "scuttler husk": { name: "Scuttler Husk", url: "https://wiki.warframe.com/w/Scuttler_Husk", revid: 2795829, fetched: "2026-10-03T20:35:15.619135Z", foundText: "Scuttler Husk is a special resource from Duviri acquired from Isleweaver.", drops: [], otherSections: [{ heading: "Acquisition", text: "Awarded from defeating The Fragmented in Isleweaver, 16-20 Scuttler Husk are awarded normally, with 20-24 awarded in The Steel Path. These amounts are not affected by Resource Boosters." }, { heading: "Vendor Purchases", text: `Oraxia Blueprint 60 Oraxia Neuroptics 20 Oraxia Chassis 20 Oraxia Systems 20 Oraxia Blueprint (Helminth) 60 Oraxia Neuroptics (Helminth) 20 Oraxia Chassis (Helminth) 20 Oraxia Systems (Helminth) 20 Scyotid Blueprint 48 Scyotid Gauntlet 1 12 Scyotid Gauntlet 2 12 Scyotid Barrel 1 12 Scyotid Barrel 2 12 Spinnerex Blueprint 48 Spinnerex Blade 16 Spinnerex Handle 16 Spinnerex String 16 96 Octopede Arena Scene Captura Scene 25 Isleweaver Cloud Islet Scene Captura Scene 25 Isleweaver Drift Atoll Scene Captura Scene 25 Scholar's Landing Scene Captura Scene 25 Duviri Throne Room Scene Captura Scene 25 "Along Came" Honoria 100 Scuttler Husk can be used to purchase Oraxia, Scyotid, Spinnerex, Thalys and Captura scenes. Kuva has purchase limit of 7 times per week. 120 are needed to purchase all parts of Oraxia, 96 for all parts of Scyotid (2x Barrel and Gauntlet), 96 for all parts of Spinnerex, 96 for the Thalys blueprint, and 125 for all Captura scenes, for a total of 533 Scuttler Husk needed to purchase everything (this total increases to 653 if you wish to purchase a second Oraxia for Helminth purposes). However, only the Captura scenes and the Thalys blueprint are shop-exclusive, reducing this total to 221 Scuttler Husk if you are willing to farm the rest. Note: Acrithis will only exchange Scuttler Husks in the Dormizone. This option is absent if she is interacted within Duviri. \u25BE View Exchange Scuttler Husks List \u25BE 60 Oraxia Blueprint 20 Oraxia Chassis Blueprint 20 Oraxia Neuroptics Blueprint 20 Oraxia Systems Blueprint 48 Scyotid Blueprint 12 Scyotid Barrel Blueprint 12 Scyotid Gauntlet Blueprint 96 Thalys Blueprint 48 Spinnerex Blueprint 16 Spinnerex Blade Blueprint 16 Spinnerex Handle Blueprint 16 Spinnerex String Blueprint 25 Octopede Arena Scene 25 Isleweaver Cloud Islet Scene 25 Isleweaver Drift Atoll Scene 25 Scholar's Landing Scene 25 Duviri Throne Room Scene 100 Kuva (6,000)` }] },
  "secondary arcane adapter": { name: "Secondary Arcane Adapter", url: "https://wiki.warframe.com/w/Secondary_Arcane_Adapter", revid: 2795875, fetched: "2026-10-03T20:35:15.619135Z", foundText: "Can sometimes be acquired from The Descendia Can be purchased from Teshin's Steel Path Honors for 15 Steel Essence. Can be purchased from Acrithis's shop for 25 Pathos Clamp. Can be purchased from the Market for 20 Platinum.", drops: [], otherSections: [{ heading: "Acquisition", text: "Can sometimes be acquired from The Descendia Can be purchased from Teshin's Steel Path Honors for 15 Steel Essence. Can be purchased from Acrithis's shop for 25 Pathos Clamp. Can be purchased from the Market for 20 Platinum. Must unlock The Steel Path for the listing to appear in the market." }, { heading: "Acquisition", text: "*Can sometimes be acquired from The Descendia" }] },
