  "shrill voca": { name: "Shrill Voca", url: "https://wiki.warframe.com/w/Shrill_Voca", revid: 2706739, fetched: "2026-10-03T20:35:15.619135Z", foundText: "Shrill Voca is a common resource found within Albrecht's Laboratories on Deimos.", drops: [{ missionType: "Disruption", source: "Deimos Entrati Disruption", rotationOrTable: "A", chance: 0.0909, quantity: 1, nodes: ["Armatus, Deimos"] }, { missionType: "Sanctum Anatomica Bounty", source: "Sanctum Anatomica Bounty 55-60", rotationOrTable: "A", chance: 0.1304, quantity: 1, nodes: ["Sanctum Anatomica, Deimos; talk to Fibonacci"] }, { missionType: "Sanctum Anatomica Bounty", source: "Sanctum Anatomica Bounty 65-70", rotationOrTable: "A", chance: 0.1356, quantity: 1, nodes: ["Sanctum Anatomica, Deimos; talk to Fibonacci"] }], otherSections: [{ heading: "Acquisition", text: "Shrill Voca can be found scattered across any Albrecht's Laboratories mission as an interactable pickup. Tier 1 and 2 Bounties from Fibonacci have a chance to award a Shrill Voca. Every 8 hours, one Shrill Voca can be purchased from Loid using resources found in the Albrecht's Laboratories." }, { heading: "Enemy Drop Tables", text: "Drop Table Chance [ 4 ] Item Chance [ 1 ] Chance [ 5 ] Expected Kills [ 6 ] Quantity [ 2 ] Avg. Per roll attempt [ 7 ] No enemy drop tables with this item Sourced from the official drop table repository. See Module:DropTables/data to edit on the wiki." }, { heading: "Acquisition", text: "*Shrill Voca can be found scattered across any Albrecht's Laboratories mission as an interactable pickup." }] },
  "sibear incarnon genesis": { name: "Sibear Incarnon Genesis", url: "https://wiki.warframe.com/w/Sibear_Incarnon_Genesis", revid: 2773653, fetched: "2026-10-03T20:35:15.619135Z", foundText: "Purchased from Cavalero for 120 Platinum, complete with the resources used in its installation.", drops: [], otherSections: [{ heading: "Acquisition", text: "Upon completion of The Duviri Paradox and Angels of the Zariman, and unlocking The Steel Path, players can earn Sibear Incarnon Genesis from The Circuit's Steel Path to place on their Sibear with the help of Cavalero in the Chrysalith. This Incarnon Genesis form grants it evolutions to a transformation and newfound strength. Purchased from Cavalero for 120 Platinum, complete with the resources used in its installation. This purchase can only be made once." }, { heading: "Acquisition", text: "*Upon completion of The Duviri Paradox and Angels of the Zariman, and unlocking The Steel Path, players can earn Sibear Incarnon Genesis from The Circuit's Steel Path to place on their Sibear with the help of Cavalero in the Chrysalith. This Incarnon Genesis form grants it evolutions to a transformation and newfound strength." }] },
