  "spinal core section": { name: "Spinal Core Section", url: "https://wiki.warframe.com/w/Spinal_Core_Section", revid: 2711774, fetched: "2026-10-03T20:35:15.619135Z", foundText: "Spinal Core Section is a resource obtainable from fishing and cutting Vitreospina and Chondricord, found in caves in the Cambion Drift.", drops: [], otherSections: [{ heading: "Acquisition", text: "Spinal Core Section s can be obtained by filleting Chondricord and Vitreospina (both from the Cambion Drift ) at Daughter in the Necralisk. The Isolation Vault bounty of the Cambion Drift may also award Spinal Core Section. The Sagiant Entrati Casket on the Cambion Drift can contain Spinal Core Sections." }, { heading: "Acquisition", text: "* Spinal Core Sections can be obtained by filleting Chondricord and Vitreospina (both from the Cambion Drift) at Daughter in the Necralisk." }] },
  "sporulate sac": { name: "Sporulate Sac", url: "https://wiki.warframe.com/w/Sporulate_Sac", revid: 2711770, fetched: "2026-10-03T20:35:15.619135Z", foundText: "Sporulate Sacs are a resource that can be obtained by filleting Glutinox.", drops: [], otherSections: [{ heading: "Acquisition", text: 'Sporulate Sacs can be obtained by filleting Glutinox (from the Cambion Drift ) at Daughter in the Necralisk. Each Glutinox will give 1 Sporulate Sac regardless of size. Sporulate Sacs can also be bought from Daughter from the "Daily Special" in exchange for Platinum. Note that the "Daily Special" wares are rotating, and Sporulate Sacs may not be there. Sporulate Sacs can also be randomly obtained from Requiem Obelisks Sporulate Sacs can be housed within common Rolizor Infested and rare Spitia Infested Cysts scattered around on the Cambion Drift.' }, { heading: "Acquisition", text: "* Sporulate Sacs can be obtained by filleting Glutinox (from the Cambion Drift) at Daughter in the Necralisk. Each Glutinox will give 1 Sporulate Sac regardless of size." }] },
  "spring popper": { name: "Spring Popper", url: "https://wiki.warframe.com/w/Spring_Popper", revid: 2804626, fetched: "2026-10-03T20:35:15.619135Z", drops: [], otherSections: [{ heading: "Acquisition", text: "Spring Popper can be harvested in the Deepmines Forward Base of Corporate Restructuring Deepmines Bounty. May be awarded randomly as a bonus bounty reward at the end of the mission, appearing just beside the extraction elevator. Can be purchased for 10 Fergolyte from Nightcap, requiring Rank 2 - Curious. Deepmines Forward Base (Stage 2-5 zone in Corporate Restructuring bounty) Winter Spear Weapons inflict Cold Damage. Greatly increases Movement Speed and Parkour Velocity, and greatly reduces Friction. Weapons inflict Impact Damage. Player is surrounded by particle effects similar to those of Prism. Enemies hit will likewise produce said particle effects. Spring Popper Weapons inflict Blast Damage. Enemies hit by weapons are thrown upwards with a Ragdoll effect. Weapons inflict Corrosive Damage." }, { heading: "Acquisition", text: "* can be harvested in the Deepmines Forward Base of Corporate Restructuring Deepmines Bounty." }] },
  "stance forma": { name: "Stance Forma", url: "https://wiki.warframe.com/w/Stance_Forma", revid: 2727663, fetched: "2026-10-03T20:35:15.619135Z", foundText: "Stance Forma blueprint can be purchased from The Steel Path Honors shop for 10 Steel Essence.", drops: [], otherSections: [{ heading: "Acquisition", text: "Stance Forma blueprint can be purchased from The Steel Path Honors shop for 10 Steel Essence. Manufacturing Requirements 100,000 1 1 5 Time: 24 hrs Rush: 10 Platinum Market Price: N/A Blueprints Price: N/A" }, { heading: "Acquisition", text: "*Stance Forma blueprint can be purchased from The Steel Path Honors shop for 10 Steel Essence." }] },
