  "tink dissipator coil": { name: "Tink Dissipator Coil", url: "https://wiki.warframe.com/w/Tink_Dissipator_Coil", revid: 2729087, fetched: "2026-10-03T20:35:15.619135Z", foundText: "Tink Dissipator Coil is a Resource extracted from Tink, a Servofish found in ponds during Cold/Freezing Weather in Orb Vallis.", drops: [], otherSections: [{ heading: "Acquisition", text: 'Tink Dissipator Coils are acquired by dismantling Tinks caught through Fishing. Go to The Business in Fortuna, select the desired amount of Tinks available, and select the " Dismantle " option to extract the components. Each Tink yields one Tink Dissipator Coil.' }, { heading: "Acquisition", text: 'Tink Dissipator Coils are acquired by dismantling Tinks caught through Fishing. Go to The Business in Fortuna, select the desired amount of Tinks available, and select the "Dismantle" option to extract the components.' }] },
