  vainthorn: { name: "Vainthorn", url: "https://wiki.warframe.com/w/Vainthorn", revid: 2815501, fetched: "2026-10-03T20:35:15.619135Z", drops: [], otherSections: [{ heading: "Acquisition", text: "Vainthorns are an award from the Abyssal Zone on Ceres. Upon mission completion, one Abyssal Beacon is consumed from the player who started the mission vote. Vainthorns are awarded upon mission completion: 6, 7, or 8 are gained normally, with 8, 11, or 12 gained in The Steel Path. These amounts are not affected by Resource Boosters or the retrieval of multiple Defixio." }, { heading: "Acquisition", text: "Vainthorns are an award from the Abyssal Zone on Ceres." }] },
  "vasto incarnon genesis": { name: "Vasto Incarnon Genesis", url: "https://wiki.warframe.com/w/Vasto_Incarnon_Genesis", revid: 2814467, fetched: "2026-10-03T20:35:15.619135Z", foundText: "Purchased from Cavalero for 120 Platinum, complete with the resources used in its installation.", drops: [], otherSections: [{ heading: "Acquisition", text: "Upon completion of The Duviri Paradox and Angels of the Zariman, and unlocking The Steel Path, players can earn Vasto Incarnon Genesis from The Circuit's Steel Path to place on their Vasto with the help of Cavalero in the Chrysalith. This Incarnon Genesis form grants it evolutions to a transformation and newfound strength. Purchased from Cavalero for 120 Platinum, complete with the resources used in its installation. This purchase can only be made once." }, { heading: "Acquisition", text: "*Upon completion of The Duviri Paradox and Angels of the Zariman, and unlocking The Steel Path, players can earn Vasto Incarnon Genesis from The Circuit's Steel Path to place on their Vasto with the help of Cavalero in the Chrysalith. This Incarnon Genesis form grants it evolutions to a transformation and newfound strength." }] },
