  "zylok incarnon genesis": { name: "Zylok Incarnon Genesis", url: "https://wiki.warframe.com/w/Zylok_Incarnon_Genesis", revid: 2814468, fetched: "2026-10-03T20:35:15.619135Z", foundText: "Purchased from Cavalero for 120 Platinum, complete with the resources used in its installation.", drops: [], otherSections: [{ heading: "Acquisition", text: "Upon completion of The Duviri Paradox and Angels of the Zariman, and unlocking The Steel Path, players can earn Zylok Incarnon Genesis from The Circuit's Steel Path to place on their Zylok with the help of Cavalero in the Chrysalith. This Incarnon Genesis form grants it evolutions to a transformation and newfound strength. Purchased from Cavalero for 120 Platinum, complete with the resources used in its installation. This purchase can only be made once." }, { heading: "Acquisition", text: "*Upon completion of The Duviri Paradox and Angels of the Zariman, and unlocking The Steel Path, players can earn Zylok Incarnon Genesis from The Circuit's Steel Path to place on their Zylok with the help of Cavalero in the Chrysalith. This Incarnon Genesis form grants it evolutions to a transformation and newfound strength." }] }
